questionvariables.text:
/* [modulus, constant]: a^2 + cc is never divisible by md. */
clist: [[3, 1], [4, 1], [4, 2], [5, 2], [5, 3]];
cpick: rand(clist);
md: cpick[1];
cc: cpick[2];
ta1: makelist(mod(jj^2 + cc, md), jj, 0, md - 1);
/* Diagnostics: not reduced; forgot the constant; forgot to square. */
dunred: makelist(jj^2 + cc, jj, 0, md - 1);
dsq: makelist(mod(jj^2, md), jj, 0, md - 1);
dlin: makelist(mod(jj + cc, md), jj, 0, md - 1);
rtable: makelist([jj, jj^2 + cc, mod(jj^2 + cc, md)], jj, 0, md - 1);
/* Validators run with simp:false, where -1 and 4/2 are not yet integers, so simplify first. */
validate_remlist(ex) := block([vv], vv: ev(ex, simp), if not(listp(vv)) then "Type a list in square brackets, separated by commas."
  else if length(vv) # md then sconcat("Type exactly ", md, " numbers, one for each remainder r.")
  else if not(every(integerp, vv)) then "Type whole numbers only." else "");
s_assert(member(0, ta1), false);
s_assert(is(length(unique([ta1, dunred, dsq, dlin])) = 4), true);
